const r={ui:{fig:"Fig. 1",title:"Forrar una bolsa · paso a paso",svgLabel:"Dibujo isométrico de cómo se forra una bolsa: el forro con una abertura, el exterior metido dentro, la costura de arriba, la vuelta por la abertura, la abertura cerrada y el pespunte.",prev:"Paso anterior",dot:(e,a)=>e?`Paso ${e}: ${a}`:a,start:"Pasos →",next:"Siguiente →",overview:"Vista general",stepOf:(e,a)=>`Paso ${e} de ${a}`,machine:e=>`Máquina: ${e.toLowerCase()}`,inThisStep:"En este paso",takeApart:"Desarmar",putTogether:"Armar",replay:"↻ Repetir",parts:"Piezas",allSteps:"Instrucciones paso a paso",endView:"CORTE"},stitches:{straight:"Puntada recta"},labels:{liningInsideOut:"forro del revés",opening8:"abertura de 8 cm",outerRightOut:"exterior al derecho",cm6:"6 cm",strapsBetween:"asas en medio",rightSides:"derecho con derecho",seam05:"costura 0,5 cm",turnThrough:"vuelta por la abertura",rightSideOut:"al derecho",tuckEdges:"meter los bordes",stitchEdge:"coser al ras del borde",pushLining:"meter el forro dentro",pressEdge:"planchar el borde",topstitch1:"pespunte a 1 cm"},steps:[{title:"La bolsa con forro",text:"El exterior y el forro se cosen juntos por el borde superior, se les da la vuelta por una abertura del forro y se pespuntean. Toca la bolsa para desarmarla."},{title:"Cose el forro con una abertura",text:"Cose el forro igual que el exterior, sin darle la vuelta, pero con una abertura de 8 cm abajo, en una costura lateral. Por ella le darás la vuelta a la bolsa.",details:["Cose el forro de la misma manera que el exterior y déjalo del revés.","En una costura lateral deja una abertura: en la tote bag mide 8 cm, abajo, justo por encima del fondo.","La abertura puede tener cualquier largo, siempre que la bolsa pase por ella. Una pieza rígida necesita más espacio: la cesta de tela, con las paredes reforzadas con entretela, tiene una abertura de 15 cm en una costura de esquina."]},{title:"Mete el exterior en el forro",text:"Da la vuelta al exterior al derecho y mételo dentro del forro, que está del revés, derecho con derecho. Las asas quedan en medio, sujetas a 6 cm del centro.",details:["Da la vuelta al exterior al derecho; el forro se queda del revés.","En la tote bag, primero sujeta con alfileres las asas al borde superior del exterior: los extremos al ras del borde, a 6 cm del centro, y las asas colgando hacia abajo sobre la bolsa.","Mete el exterior dentro del forro de modo que los derechos queden enfrentados y las asas atrapadas en medio. Alinea las costuras laterales y los bordes superiores y sujétalos con pinzas."]},{title:"Cose el borde superior",text:"Cose todo el contorno de arriba a 0,5 cm del borde, a través del forro, las asas y el exterior.",details:["Cose todo el contorno de arriba a 0,5 cm del borde, a través de todas las capas: el forro, las asas y el exterior.","La tote bag y la cesta llevan aquí la misma costura: 0,5 cm."]},{title:"Da la vuelta por la abertura",text:"Mete la mano por la abertura del forro y saca toda la bolsa por ella. El exterior sale al derecho y el forro sobresale por encima.",details:["Mete la mano por la abertura del forro, toma el exterior y saca toda la bolsa por ella.","Alisa el exterior: ya está al derecho. El forro también está al derecho y sobresale por encima de la bolsa, con la abertura aún sin cerrar."]},{title:"Cierra la abertura",text:"Mete hacia dentro los bordes de la abertura siguiendo la línea de la costura y ciérrala a máquina, al ras del borde. O ciérrala con punto invisible a mano.",details:["Mete hacia dentro los bordes sin acabar de la abertura, en línea con el resto de la costura, de modo que los dos dobleces se junten.","Primera forma, a máquina: cose los dos dobleces juntos al ras del borde. Así se cierran la tote bag y la cesta; después la costura queda escondida dentro de la bolsa.","Segunda forma, con punto invisible a mano: plancha los dos dobleces, enhebra la aguja con hilo del color de la tela y esconde el nudo dentro de un doblez.","Da una puntada pequeña dentro de un doblez y luego, justo enfrente, otra puntada pequeña dentro del otro. Sigue así, de un lado al otro: los hilos entre los dobleces parecen los peldaños de una escalera.","Cada dos o tres puntadas, tira del hilo: los bordes se cierran y las puntadas desaparecen. Al final, remata el hilo y esconde la punta dentro del forro."]},{title:"Mete el forro dentro",text:"Empuja el forro hacia dentro de la bolsa y plancha el borde superior para que quede plano.",details:["Empuja el forro hacia dentro del exterior, hasta el fondo.","En la tote bag, plancha el borde superior para que quede plano. En la cesta, alisa el forro en las esquinas."]},{title:"Pespuntea el borde superior",text:"Pespuntea todo el contorno de arriba a 1 cm del borde. En la cesta, el pespunte va a 0,5 cm del borde.",details:["Pespuntea todo el contorno de arriba, a través del exterior y el forro: a 1 cm del borde en la tote bag, a 0,5 cm en la cesta.","¡Tu bolsa está lista!"]}],legend:[{title:"Exterior",text:"al derecho · en la tote bag, las asas van cosidas en su borde superior, a 6 cm del centro"},{title:"Forro",text:"cosido igual que el exterior, del revés; luego se le da la vuelta y se mete dentro"},{title:"Abertura",text:"en una costura del forro: 8 cm en una costura lateral de la tote bag, 15 cm en una costura de esquina de la cesta · cerrada al ras del borde"},{title:"Costura superior",text:"exterior y forro derecho con derecho, a 0,5 cm del borde"},{title:"Pespunte",text:"a 1 cm del borde superior en la tote bag, a 0,5 cm en la cesta"}]};export{r as default};
